+                case STANDARD -> "520.00";
+                case DELUXE -> "820.00";
+                case SUITE -> "1200.00";
+            }));
+            return new Price(seasonal.nights(), closedPrice, PriceCalculator.cents(BigDecimal.ZERO), closedPrice);
