    32	            }
    33	        }
    34	
    35	        @Override
    36	        Price price(NewReservation request, Room room, Price seasonal) {
    37	            Company company = Company.find(request.companyCode()).orElseThrow();
    38	            return seasonal.withDiscount(PriceCalculator.cents(seasonal.subtotal().multiply(company.discount())));
    39	        }
    40	    },
    41	    /** Friday to Sunday, two nights, for a closed price all year round; half comes back on cancellation. */
    42	    WEEKEND_PACKAGE {
    43	        @Override
    44	        void validate(NewReservation request) {
    45	            if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY
    46	                    || !request.checkOut().equals(request.checkIn().plusDays(2))) {
    47	                throw invalid("the weekend package is from a Friday to the Sunday after it");
    48	            }
    49	        }
    50	
