    53	            BigDecimal closedPrice = PriceCalculator.cents(new BigDecimal(switch (room.type()) {
    54	                case STANDARD -> "520.00";
    55	                case DELUXE -> "820.00";
    56	                case SUITE -> "1200.00";
    57	            }));
    58	            return new Price(seasonal.nights(), closedPrice, PriceCalculator.cents(BigDecimal.ZERO), closedPrice);
