    99	package hotel.reservations;
   100	
   101	import hotel.rooms.Room;
   102	import java.math.BigDecimal;
   103	import java.math.RoundingMode;
   104	import java.time.LocalDate;
   105	import java.time.Month;
   106	
   107	/**
   108	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   109	 * high-season nights; the rate plan then prices the stay from that (a discount on the sum, or a closed price). Money is rounded to cents
   110	 * (half-even) at every step.
   111	 */
   112	public final class PriceCalculator {
   113	
   114	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   115	
   116	    public Price calculate(Room room, NewReservation request) {
   117	        int nights = 0;
   118	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   119	        for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
   120	            subtotal = subtotal.add(nightPrice(room, night));
   121	            nights++;
   122	        }
   123	        Price seasonal = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
   124	        return request.ratePlan().price(request, room, seasonal);
   125	    }
   126	
   127	    BigDecimal nightPrice(Room room, LocalDate night) {
   128	        BigDecimal nightlyRate = room.nightlyRate();
   129	        if (isHighSeason(night)) {
   130	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   131	        }
   132	        return cents(nightlyRate);
   133	    }
   134	
   135	    /** High season: from December 15 to the end of February, and the whole of July. */
   136	    static boolean isHighSeason(LocalDate date) {
   137	        Month month = date.getMonth();
   138	        return month == Month.JANUARY
   139	                || month == Month.FEBRUARY
   140	                || month == Month.JULY
   141	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   142	    }
   143	
   144	    static BigDecimal cents(BigDecimal value) {
   145	        return value.setScale(2, RoundingMode.HALF_EVEN);
   146	    }
   147	}
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        request.ratePlan().validate(request);
    35	        Room room = rooms.find(request.roomNumber())
    36	                .orElseThrow(() -> new HotelException(
    37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    38	        if (request.guests() > room.capacity()) {
    39	            throw new HotelException(
    40	                    ErrorCode.CAPACITY_EXCEEDED,
    41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    42	        }
    43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request);
    48	        return store.add(request, price);
    49	    }
    50	
    51	    public Reservation find(long reservationId) {
    52	        return store.find(reservationId)
    53	                .orElseThrow(() -> new HotelException(
    54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    55	    }
    56	
    57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    58	    public synchronized Reservation confirm(long reservationId) {
    59	        Reservation reservation = find(reservationId);
    60	        if (reservation.status() != ReservationStatus.PENDING) {
    61	            throw notAllowed(reservation, "confirm");
    62	        }
    63	        reservation.confirmPayment();
    64	        store.update(reservation);
    65	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    66	        emailSender.send(
    67	                reservation.guest().email(),
    68	                "Reserva confirmada - " + HOTEL_NAME,
    69	                confirmationEmailBody(reservation, receipt));
    70	        return reservation;
    71	    }
    72	
    73	    /**
    74	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    75	     * reservation was never paid, so nothing comes back).
    76	     */
    77	    public synchronized Reservation cancel(long reservationId) {
    78	        Reservation reservation = find(reservationId);
    79	        if (reservation.status() != ReservationStatus.PENDING
    80	                && reservation.status() != ReservationStatus.CONFIRMED) {
    81	            throw notAllowed(reservation, "cancel");
    82	        }
    83	        BigDecimal refund = reservation.ratePlan().refund(reservation.amountPaid());
    84	        reservation.cancel(refund);
    85	        store.update(reservation);
    86	        return reservation;
